<script setup lang="ts">
import {onMounted,ref,computed} from 'vue';
import {type Lang,type Mission,type State,loadSave,start,save,objectiveDone,execute,claim} from './engine';
const lang=ref<Lang>((localStorage.getItem('cloud-lang') as Lang)||'zh');const missions=ref<Mission[]>([]);const world=ref<State|null>(loadSave());const current=ref<Mission|null>(null);const page=ref('home');const command=ref('');const output=ref('');const error=ref('');const hint=ref(0);
const t=(x:Record<Lang,string>|undefined)=>x?.[lang.value]||x?.en||'';
const done=computed(()=>current.value&&world.value?current.value.objectives.map(o=>objectiveDone(o,world.value!)):[]);
const unlocked=(id:string)=>{const i=missions.value.findIndex(m=>m.id===id);return i===0||(i>0&&!!world.value?.completed[missions.value[i-1].id])};
async function choose(id:string){try{const r=await fetch(import.meta.env.BASE_URL+'missions/'+id+'.json');if(!r.ok)throw new Error('Mission JSON not found: '+id);current.value=await r.json();if(world.value?.missionId!==id)world.value=start(current.value!,world.value);save(world.value!);page.value='mission';error.value='';hint.value=0}catch(e){error.value=String(e)}}
function run(){if(!world.value||!current.value)return;output.value=execute(command.value,world.value,current.value);command.value=''}
function finish(){if(world.value&&current.value)output.value=claim(world.value,current.value)?'Mission complete!':'Objectives not met / preview engine incomplete.'}
function reset(){if(current.value){world.value=start(current.value,world.value);save(world.value);output.value='Reset'}}
onMounted(async()=>{try{const r=await fetch(import.meta.env.BASE_URL+'catalog.json');if(!r.ok)throw Error('catalog.json missing');const data=await r.json();missions.value=data.missions.filter((m:{playable:boolean})=>m.playable);if(world.value?.missionId)await choose(world.value.missionId)}catch(e){error.value=String(e)}});
function setLang(e:Event){lang.value=(e.target as HTMLSelectElement).value as Lang;localStorage.setItem('cloud-lang',lang.value)}
</script>
<template><div class="shell"><header><b>☁ AWS CLOUD OPS ADVENTURE</b><span>2035 · Commander Nova</span><select :value="lang" @change="setLang"><option value="zh">中文</option><option value="ja">日本語</option><option value="en">English</option></select></header><nav><button v-for="p in ['home','map','mission','console','topology','learning','settings']" :key="p" @click="page=p">{{({home:'指挥中心',map:'任务地图',mission:'当前任务',console:'资源控制台',topology:'拓扑',learning:'知识库',settings:'设置'} as Record<string,string>)[p]}}</button></nav><div class="notice">Educational simulator — no real AWS usage or charges. Web preview: not yet feature-equivalent to Android.</div><p v-if="error" class="error">{{error}}</p><section v-if="page==='home'"><h1>云端运维指挥官</h1><p>Shadow Fault 正在攻击云城。通过模拟任务学习云运维。</p><p>🏅 XP {{world?.xp||0}} · 🪙 {{world?.coins||0}} · 完成 {{Object.keys(world?.completed||{}).length}} / {{missions.length}}</p><button class="primary" @click="page='map'">开始 / 继续游戏</button></section><section v-else-if="page==='map'"><h2>任务地图 · {{missions.length}} missions</h2><div class="grid"><button v-for="m in missions" :key="m.id" :disabled="!unlocked(m.id)" @click="choose(m.id)">{{world?.completed[m.id]?'✓':'◈'}} {{m.id}} · {{t(m.title)}}</button></div></section><section v-else-if="page==='mission'"><template v-if="current&&world"><h2>{{t(current.title)}}</h2><p>{{t(current.story)}}</p><h3>目标</h3><div v-for="(o,i) in current.objectives" :key="i" class="objective">{{done[i]?'✅':'⬜'}} {{o.kind}} · {{o.resource}} · {{o.key}} = {{o.value}}</div><h3>Mira</h3><p>{{t(current.hints[hint])}}</p><button @click="hint=(hint+1)%current.hints.length">下一条提示</button><button class="primary" @click="finish">检查 / 领取奖励</button><button @click="reset">重置本关</button></template><p v-else>请先从地图选择任务。</p></section><section v-else-if="page==='console'"><h2>资源控制台 / CLI</h2><p>输入 <code>sim help</code> 查看预览版命令。</p><form @submit.prevent="run"><input v-model="command" placeholder="sim create base-c type=base az=ap-northeast-1c"><button class="primary">执行</button></form><pre>{{output}}</pre><table><thead><tr><th>ID</th><th>Type</th><th>Region</th><th>Attrs</th></tr></thead><tbody><tr v-for="r in world?.resources||[]" :key="r.id"><td>{{r.id}}</td><td>{{r.type}}</td><td>{{r.region}}</td><td>{{JSON.stringify(r.attrs)}}</td></tr></tbody></table></section><section v-else-if="page==='topology'"><h2>拓扑</h2><div class="grid"><div class="node" v-for="r in world?.resources||[]" :key="r.id">☁ {{r.id}} · {{r.type}}</div></div><p>拖动与连线仍待移植。</p></section><section v-else-if="page==='learning'"><h2>知识库</h2><p>{{t(current?.lesson)}}</p></section><section v-else><h2>设置</h2><p>本地存档：浏览器 localStorage。</p></section><footer>Independent learning simulator, not affiliated with AWS.</footer></div></template>